const qrCodeModuleBase64 = "";

type QRCodeModule = {
  toDataURL: (text: string, options?: Record<string, unknown>) => Promise<string>;
};

let qrCodeModulePromise: Promise<QRCodeModule> | undefined;

async function loadQRCodeModule(): Promise<QRCodeModule> {
  if (!qrCodeModulePromise) {
    const source = atob(qrCodeModuleBase64);
    const blobURL = URL.createObjectURL(new Blob([source], { type: "text/javascript" }));
    qrCodeModulePromise = import(/* @vite-ignore */ blobURL)
      .then((module) => module as QRCodeModule)
      .finally(() => URL.revokeObjectURL(blobURL));
  }
  return qrCodeModulePromise;
}

export async function createQRCodeDataURL(value: string): Promise<string> {
  const qrCode = await loadQRCodeModule();
  return qrCode.toDataURL(value, {
    errorCorrectionLevel: "M",
    margin: 3,
    width: 256,
    color: { dark: "#000000ff", light: "#ffffffff" },
  });
}
